const toolNames={hand:'Manos libres',screwdriver:'Destornillador',wrench:'Llave',meter:'Multímetro'};
export function mountHandsMaintenance({onCase=()=>{},onState=()=>{},createBench=(c,h)=>new MaintenanceBench102(c,h)}={}){const $=id=>document.getElementById(id),root=$('maintenance-hands-panel');root.dataset.rebuild102='true';let bench=null,bag156=null,completed=false,started=Date.now(),rendering=false,lastActions='',lastStage='',lastLog='';const session=new MaintenanceSession102(()=>render()),state=session.state;
 root.innerHTML=`<div class="m102-heading"><div><span class="eyebrow">TALLER · INTERVENCIÓN PRÁCTICA</span><h2>Diagnostica. Repara. Comprueba.</h2></div><button id="hands-reset">Reiniciar práctica</button></div><div id="hands-case-cards" class="m102-cases">${Object.entries(HAND_CASES).map(([id,c],i)=>`<button data-repair-case="${id}"><small>0${i+1}</small><b>${c.title}</b><span>Intervenir en el tren →</span></button>`).join('')}</div><div class="m102-layout"><section class="m102-work"><div class="m102-topbar"><span>Tren estacionado · equipos instalados</span><div><button id="train156-overview">Ver tren</button><button id="game92-refocus">Acercar equipo</button><button id="game92-release">Soltar · Esc</button></div></div><div class="m102-stage"><canvas id="repair102-canvas" aria-label="Tren 3D: haz clic sobre una pieza o arrástrala a su destino"></canvas><output id="repair102-hover">Apunta a una pieza</output></div><p id="hands-view-note" hidden></p><div class="m102-tools" role="group" aria-label="Herramientas">${Object.entries(toolNames).map(([id,n],i)=>`<button data-tool="${id}" data-hotkey="${i+1}"><kbd>${i+1}</kbd>${n}</button>`).join('')}<label><input id="repair102-guided" type="checkbox" checked> Herramienta automática</label></div><div class="m102-instruments"><span id="hands-power-state"></span><span id="hands-held-piece"></span><output id="hands-meter-value"></output><button id="repair142-focus">Ver instrumento</button><button id="repair102-clear">Retirar puntas</button></div><div id="hands-live-message" role="status" aria-live="polite"></div><div class="m102-targets"><small>ACTÚA SOBRE LA PIEZA EN 3D O UTILIZA SU BOTÓN</small><div id="hands-pieces"></div></div><p class="m102-help">Clic: tomar / colocar · Arrastrar: mover una pieza · Fijaciones: mantén pulsado, gira o utiliza cuatro clics · Botón derecho: desplazar · Rueda: acercar</p></section><aside class="m102-guide"><div class="m102-guide-title"><span>MANUAL DE LA MISIÓN</span><button id="hands-manual">Ver completo</button></div><p id="hands-symptom"></p><small id="hands-step"></small><h3 id="hands-step-title"></h3><p id="hands-instruction"></p><progress id="hands-progress"></progress><ol id="hands-checklist"></ol><div id="repair102-turn"></div><button id="hands-hint">Mostrar siguiente acción</button><details><summary>Registro de intervención</summary><ol id="hands-log"></ol></details><p class="m102-scope">Intervención didáctica sobre el tren. Lecturas, piezas y maniobras simuladas. El ejercicio eléctrico utiliza 24 V CC; no sustituye procedimientos de intervención de un tren real.</p></aside></div><section id="hands-result" hidden><b>✓ Intervención comprobada</b><p>El ensayo del equipo instalado confirmó la reparación. Puedes reiniciar o elegir otra práctica.</p></section><div id="hands-drag-ghost" hidden></div><dialog id="hands-manual-dialog"><h2 id="hands-manual-title"></h2><ol id="hands-manual-steps"></ol><button id="hands-manual-close">Cerrar manual</button></dialog>`;
 const game117=new MissionGame117(root,{getBench:()=>bench,restart:id=>restart(id),onAction:id=>action(id),doc:document,win:window});$('repair102-canvas').setAttribute('tabindex','0');
 function text116(node,value){const text=String(value??'');if(node.textContent!==text)node.textContent=text;}
 function actions(){const expected=session.expected(),key=state.id+':'+expected.join(',');if(key===lastActions)return;lastActions=key;$('hands-pieces').replaceChildren(...expected.map(id=>{const b=document.createElement('button');b.dataset.target=id;b.textContent=LABELS102[id]||id;b.onclick=()=>action(id);return b;}));}
 function render(){if(rendering)return;rendering=true;try{const c=HAND_CASES[state.id],index=state.stage;text116($('hands-symptom'),c.symptom);text116($('hands-step'),state.complete?'COMPROBADO':`PASO ${index+1} DE ${c.steps.length}`);text116($('hands-step-title'),state.complete?'Equipo recuperado':c.steps[index][0]);text116($('hands-instruction'),state.complete?'La reparación y el ensayo están completos.':c.steps[index][1]);$('hands-progress').max=c.steps.length;$('hands-progress').value=index;text116($('hands-live-message'),state.message);text116($('hands-power-state'),state.power?'● Alimentación de ensayo habilitada':'○ Equipo virtual sin alimentación');$('hands-power-state').dataset.live=String(state.power);text116($('hands-held-piece'),state.selectedItem?'En el guante: '+LABELS102[state.selectedItem]:'Guante libre');text116($('hands-meter-value'),state.id==='electrical'?state.reading().value+' · '+state.reading().label:'');$('repair142-focus').hidden=state.id!=='electrical';$('repair102-clear').hidden=state.id!=='electrical'||!Object.values(state.probes).some(Boolean);const stageKey=state.id+':'+index;if(lastStage!==stageKey){lastStage=stageKey;$('hands-checklist').replaceChildren(...c.steps.map(([title],i)=>{const li=document.createElement('li');li.textContent=title;li.dataset.state=i<index?'done':i===index?'current':'pending';return li;}));}const logKey=state.id+':'+state.log.join('|');if(logKey!==lastLog){lastLog=logKey;$('hands-log').replaceChildren(...state.log.slice(-8).map(s=>{const li=document.createElement('li');li.textContent=s;return li;}));}text116($('repair102-turn'),state.toolMotion?`Giro de ${LABELS102[state.toolMotion.target]}: ${Math.round(state.toolMotion.progress*100)} %`:'');for(const b of root.querySelectorAll('[data-tool]'))b.setAttribute('aria-pressed',String(b.dataset.tool===state.tool));for(const b of root.querySelectorAll('[data-repair-case]'))b.setAttribute('aria-pressed',String(b.dataset.repairCase===state.id));actions();$('hands-hint').disabled=state.complete;$('hands-result').hidden=!state.complete;if(state.complete&&!completed){completed=true;try{const r=JSON.parse(localStorage.getItem('metro-repairs82')||'{}');r[state.id]={date:new Date().toISOString(),seconds:Math.round((Date.now()-started)/1000),version:125,readings:state.verifiedReadings||[]};localStorage.setItem('metro-repairs82',JSON.stringify(r));}catch{}globalThis.dispatchEvent?.(new Event('metro-repair-completed'));}bag156?.sync(state.tool);bench?.update(state);game117.update(state,(Date.now()-started)/1000);onState(state);}finally{rendering=false;}}
 function restart(id=state.id){bag156?.close();bag156?.prepared176.clear();game117.reset();bench?.cancel(false);if(bench)bench.doorMotion=null;completed=false;started=Date.now();session.reset(id);onCase(id);if(bench&&document.body.dataset.gameScreen==='maintenance')void gate142('Preparando tren en la vía de mantenimiento',async()=>{await readyMission197();game117.brief();});}
 function action(id){if(!bag156?.require176(session.toolFor(id)))return;if((id==='openTest'||id==='closeTest')&&bench){bench.runDoor(id==='openTest'?100:0);return;}session.action(id);}
 for(const b of root.querySelectorAll('[data-repair-case]'))b.onclick=()=>restart(b.dataset.repairCase);for(const b of root.querySelectorAll('[data-tool]'))b.onclick=()=>{bench?.cancel(false);session.use(b.dataset.tool);};$('repair102-guided').onchange=()=>{session.guided=$('repair102-guided').checked;state.message=session.guided?'La herramienta adecuada se equipa al tocar la pieza.':'Selecciona tú la herramienta antes de intervenir.';render();};$('hands-reset').onclick=()=>restart();$('game92-release').onclick=()=>{bench?.cancel(false);session.cancel();};$('game92-refocus').onclick=()=>bench?.resetView();$('repair142-focus').onclick=()=>bench?.focusInstrument142();$('repair102-clear').onclick=()=>{bench?.cancel(false);session.action('clearProbes');};$('hands-hint').onclick=()=>{state.message='Ahora toca: '+session.expected().map(id=>LABELS102[id]).join(' o ')+'. Las piezas válidas se iluminan en verde.';render();};$('hands-manual').onclick=()=>{const c=HAND_CASES[state.id];text116($('hands-manual-title'),c.title);$('hands-manual-steps').replaceChildren(...c.steps.map(([a,b])=>{const li=document.createElement('li');li.textContent=a+': '+b;return li;}));$('hands-manual-dialog').showModal();};$('hands-manual-close').onclick=()=>$('hands-manual-dialog').close();
 bag156=new ToolBag156({host:root,tools:root.querySelector('.m102-tools'),getId:b=>b.dataset.tool,getContext:()=>bench?{view:bench,glove:bench.glove,hand:bench.hand117,onPrepared176:()=>render()}:null,onEquip:(id,{prepared=false}={})=>{if(!prepared){session.guided=false;$('repair102-guided').checked=false;bench?.equipFromBag156(id);}}});if(bench)bench.prepared176=bag156.prepared176;$('train156-overview').onclick=()=>bench?.overview156();
 render();try{bench=createBench($('repair102-canvas'),{pick:action,turn:(id,a)=>{if(bag156?.require176(session.toolFor(id)))session.action(id,a);},door:v=>session.door(v),wheel:v=>session.wheel(v),cancel:()=>session.cancel(),miss:(message)=>{state.message=message||'Toca una pieza iluminada o utiliza el botón con su nombre.';render();},asset:message=>{text116($('repair102-hover'),message);},hover:(id,expected)=>{text116($('repair102-hover'),id?LABELS102[id]||id:'Siguiente: '+expected.map(x=>LABELS102[x]).join(' / '));}});bench.prepared176=bag156.prepared176;bench.update(state);}catch(e){$('repair102-canvas').hidden=true;$('hands-view-note').hidden=false;text116($('hands-view-note'),'Vista 3D no disponible. Los botones de piezas permiten realizar las cuatro prácticas.');console.error(e);}
 async function readyMission197(){if(!bench)throw Error('Vista WebGL no disponible');await bench.ready142();const p178=bench.camera.position.clone(),d178=bench.camera.getWorldDirection(bench.camera.position.clone().set(0,0,0));d178.y=0;d178.normalize();p178.addScaledVector(d178,.65);p178.y=(bench.walk176?.floor190()||0)+.07;if(state.id==='doors')p178.z=Math.max(.58,Math.min(1.85,p178.z));await bag156.place178(p178);}
 return{state,session,action,restart,ready142:readyMission197,recenter:()=>bench?.resetView(),cancelDrag:()=>{bench?.cancel(false);session.cancel();},moveHands:e=>bench?.hand(e),hideHands:()=>{bench?.hideHand();},interact3D:action,setVisible(visible){root.hidden=!visible;if(bench){bench.visible=visible;if(!visible){bench.walk176?.releaseMouse182();bench.walk176?.keys.clear();bag156?.close();game117.close();bench.cancel(false);bench.doorMotion=null;session.cancel();bench.hideHand();}else{bench.resize();bench.resetView();render();}}}};
}
